                  and (r.from_member_id = m.id or r.to_member_id = m.id)))) then
    raise exception 'holder must be the client or a related family member' using errcode = '23514';
  end if;
  update cw_prod.financial_accounts
     set owner_member_id = case when coalesce(p_joint, false) then null else p_member end,
         joint = coalesce(p_joint, false), updated_at = now()
   where id = p_account;
end $$;
